-- Nuestra Casita. Ejecutar completo en un proyecto nuevo de Supabase.
-- Las tablas NO admiten lectura/escritura directa anon. Los RPC validan sesiones propias.
begin;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create table public.jugadores(id uuid primary key default gen_random_uuid(),usuario text unique not null check(usuario ~ '^[a-z0-9]{6,10}$'),password_hash text not null,personaje jsonb not null default '{"sexo":"hombre","piel":"#b67b50","pelo":"#30221e","estilo":0,"camisa":"#f2ab55","pantalon":"#315568"}',records jsonb not null default '{}',creado timestamptz not null default now());
create table public.sesiones(token_hash text primary key,jugador uuid not null references public.jugadores on delete cascade,expira timestamptz not null default now()+interval '30 days');
create index sesiones_jugador on public.sesiones(jugador);
create table public.casas(id uuid primary key default gen_random_uuid(),codigo text unique not null default upper(encode(extensions.gen_random_bytes(4),'hex')),canal uuid not null default gen_random_uuid(),dinero integer not null default 600 check(dinero>=0),amor integer not null default 20 check(amor between 0 and 100),compras jsonb not null default '[]',creada timestamptz not null default now(),dia integer not null default 1 check(dia>0));
create table public.miembros(jugador uuid primary key references public.jugadores on delete cascade,casa uuid not null references public.casas on delete cascade,x real not null default 0,z real not null default 0,hambre real not null default 90,energia real not null default 90,higiene real not null default 90,diversion real not null default 90,trabajos integer not null default 0,dia integer not null default 1,actualizado timestamptz not null default now(),pos_actualizada timestamptz not null default now(),accion text,inicio timestamptz,fin timestamptz,pareja boolean not null default false,check(hambre between 0 and 100 and energia between 0 and 100 and higiene between 0 and 100 and diversion between 0 and 100),check(trabajos between 0 and 1),check(x between -9 and 7 and z between -5 and 5.5));
create index miembros_casa on public.miembros(casa);
create table public.catalogo(item text primary key,nombre text not null,precio integer not null check(precio>0));
insert into public.catalogo values ('radio','Radio',900),('cortinas','Cortinas sala',1500),('cortinas2','Cortinas cuarto',1500),('planta','Planta',1200),('centro','Mesa centro',3500),('cuadro','Cuadro',1800),('crema','Pintura crema',3500),('coral','Paredes coral',4500),('menta','Paredes menta',4500),('lavamanos','Lavamanos',4500),('lampara','Lámpara',2500),('armario','Armario',8000),('sofa','Sofá',18000),('comedor','Comedor',16000),('tv','TV pequeña',9000),('patio','Mesa patio',12000),('tvgrande','TV grande',28000);
create table public.acciones(clave text primary key,segundos integer not null,costo integer not null default 0,necesidad text,ganancia integer not null default 0,amor integer not null default 0,pareja boolean not null default false,item text);
insert into public.acciones values ('nevera',9,150,'hambre',40,0,false,null),('cocinar',21,180,'hambre',55,0,false,null),('ducha',12,0,'higiene',55,0,false,null),('cama',20,0,'energia',60,0,false,null),('inodoro',6,0,'higiene',12,0,false,null),('tv',15,0,'diversion',40,0,false,'tv'),('radio',14,0,'diversion',35,0,false,'radio'),('sofa',12,0,'energia',20,0,false,'sofa'),('patio',8,0,'diversion',18,0,false,null),('armario',5,0,'diversion',12,0,false,'armario'),('trabajo',60,0,null,0,0,false,null),('abrazar',6,0,null,0,5,true,null),('besar',5,0,null,0,6,true,null),('bailar',8,0,'diversion',20,8,true,null),('pelicula',8,0,'diversion',30,8,true,'tv'),('juntos',8,250,'hambre',45,9,true,null),('flores',5,500,null,0,12,true,null),('bizcocho',8,800,'hambre',20,15,true,null),('velas',5,0,null,0,1,false,null);
alter table public.jugadores enable row level security;
alter table public.sesiones enable row level security;
alter table public.casas enable row level security;
alter table public.miembros enable row level security;
alter table public.catalogo enable row level security;
alter table public.acciones enable row level security;
revoke all on public.jugadores,public.sesiones,public.casas,public.miembros,public.catalogo,public.acciones from anon,authenticated;
create function public.nc_identidad(p_token text) returns uuid language plpgsql security definer set search_path='' as $$
declare j uuid;begin if p_token is null or length(p_token)<>64 then raise exception 'Sesión vencida. Entra otra vez.';end if;select jugador into j from public.sesiones where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') and expira>now();if j is null then raise exception 'Sesión vencida. Entra otra vez.';end if;return j;end;$$;
create function public.nc_register(p_usuario text,p_pin text) returns jsonb language plpgsql security definer set search_path='' as $$
declare j uuid;t text;begin if p_usuario is null or p_pin is null or p_usuario !~ '^[a-zA-Z0-9]{6,10}$' or p_pin !~ '^[0-9]{6}$' then raise exception 'Usuario de 6–10 letras/números y contraseña de 6 dígitos.';end if;insert into public.jugadores(usuario,password_hash) values(lower(p_usuario),extensions.crypt(p_pin,extensions.gen_salt('bf',10))) returning id into j;t:=encode(extensions.gen_random_bytes(32),'hex');insert into public.sesiones(token_hash,jugador) values(encode(extensions.digest(t,'sha256'),'hex'),j);return jsonb_build_object('token',t);exception when unique_violation then raise exception 'Ese usuario ya existe.';end;$$;
create function public.nc_login(p_usuario text,p_pin text) returns jsonb language plpgsql security definer set search_path='' as $$
declare j uuid;t text;begin if p_pin is null or p_pin !~ '^[0-9]{6}$' then raise exception 'Credenciales incorrectas.';end if;select id into j from public.jugadores where usuario=lower(p_usuario) and password_hash=extensions.crypt(p_pin,password_hash);if j is null then raise exception 'Credenciales incorrectas.';end if;t:=encode(extensions.gen_random_bytes(32),'hex');delete from public.sesiones where expira<now();insert into public.sesiones(token_hash,jugador) values(encode(extensions.digest(t,'sha256'),'hex'),j);return jsonb_build_object('token',t);end;$$;
create function public.nc_personaje(p_token text,p_personaje jsonb) returns boolean language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);k text;begin if p_personaje is null or jsonb_typeof(p_personaje)<>'object' or length(p_personaje::text)>500 or coalesce(p_personaje->>'sexo','') not in ('hombre','mujer') or coalesce(p_personaje->>'estilo','') not in ('0','1','2') then raise exception 'Personaje inválido.';end if;foreach k in array array['piel','pelo','camisa','pantalon'] loop if coalesce(p_personaje->>k,'') !~ '^#[a-fA-F0-9]{6}$' then raise exception 'Color inválido.';end if;end loop;update public.jugadores set personaje=jsonb_build_object('sexo',p_personaje->>'sexo','estilo',(p_personaje->>'estilo')::int,'piel',p_personaje->>'piel','pelo',p_personaje->>'pelo','camisa',p_personaje->>'camisa','pantalon',p_personaje->>'pantalon') where id=j;return true;end;$$;
create function public.nc_crear(p_token text) returns text language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;cod text;begin perform 1 from public.jugadores where id=j for update;select casa into c from public.miembros where jugador=j;if c is not null then raise exception 'Ya tienes casa. Usa Volver a mi casa y comparte tu código.';end if;insert into public.casas default values returning id,codigo into c,cod;insert into public.miembros(jugador,casa) values(j,c);return cod;end;$$;
create function public.nc_unirse(p_token text,p_codigo text) returns boolean language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;begin perform 1 from public.jugadores where id=j for update;if exists(select 1 from public.miembros where jugador=j) then raise exception 'Ya tienes casa. Comparte tu código con tu pareja.';end if;select id into c from public.casas where codigo=upper(p_codigo) for update;if c is null then raise exception 'Código de casa inválido.';end if;if (select count(*) from public.miembros where casa=c)>=2 then raise exception 'La casa ya tiene dos personas.';end if;insert into public.miembros(jugador,casa,x) values(j,c,1);return true;end;$$;
-- Avance autoritativo del reloj, necesidades y recompensas. No se acepta dinero del cliente.
create function public.nc_tick(p_casa uuid) returns void language plpgsql security definer set search_path='' as $$
declare c public.casas%rowtype;m public.miembros%rowtype;a public.acciones%rowtype;d int;dt real;begin select * into c from public.casas where id=p_casa for update;d:=1+floor(extract(epoch from(now()-c.creada))/2160)::int;update public.casas set dia=d where id=p_casa;for m in select * from public.miembros where casa=p_casa order by jugador for update loop dt:=greatest(0,extract(epoch from(now()-m.actualizado)))::real;update public.miembros set hambre=greatest(0,hambre-dt*50/2160),energia=greatest(0,energia-dt*31/2160),higiene=greatest(0,higiene-dt*44/2160),diversion=greatest(0,diversion-dt*44/2160),trabajos=case when dia<>d then 0 else trabajos end,dia=d,actualizado=now() where jugador=m.jugador;if m.accion is not null and m.fin<=now() then select * into a from public.acciones where clave=m.accion;if not m.pareja then if m.accion='trabajo' then update public.casas set dinero=dinero+1800 where id=p_casa;update public.miembros set trabajos=least(1,trabajos+1),energia=greatest(0,energia-10) where jugador=m.jugador;update public.jugadores set records=jsonb_set(records,'{salarios}',to_jsonb(coalesce((records->>'salarios')::int,0)+1)) where id=m.jugador;end if;update public.casas set amor=least(100,amor+a.amor) where id=p_casa;end if;update public.miembros set hambre=least(100,hambre+case when a.necesidad='hambre' then a.ganancia else 0 end),energia=least(100,energia+case when a.necesidad='energia' then a.ganancia else 0 end),higiene=least(100,higiene+case when a.necesidad='higiene' then a.ganancia else 0 end),diversion=least(100,diversion+case when a.necesidad='diversion' then a.ganancia else 0 end),accion=null,inicio=null,fin=null,pareja=false where jugador=m.jugador;end if;end loop;end;$$;
create function public.nc_estado(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;r jsonb;begin select casa into c from public.miembros where jugador=j;if c is null then raise exception 'Todavía no tienes casa.';end if;perform public.nc_tick(c);select jsonb_build_object('yo',j,'casa',jsonb_build_object('id',h.id,'codigo',h.codigo,'canal',h.canal,'dinero',h.dinero,'amor',h.amor,'compras',h.compras,'dia',h.dia,'segundos',mod(extract(epoch from(now()-h.creada))::numeric,2160)),'jugadores',(select jsonb_agg(jsonb_build_object('id',m.jugador,'usuario',p.usuario,'personaje',p.personaje,'x',m.x,'z',m.z,'hambre',m.hambre,'energia',m.energia,'higiene',m.higiene,'diversion',m.diversion,'trabajos',m.trabajos,'accion',m.accion,'inicio',extract(epoch from m.inicio),'fin',extract(epoch from m.fin))) from public.miembros m join public.jugadores p on p.id=m.jugador where m.casa=c)) into r from public.casas h where h.id=c;return r;end;$$;
create function public.nc_comprar(p_token text,p_item text) returns boolean language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;precio int;h public.casas%rowtype;begin select casa into c from public.miembros where jugador=j;select * into h from public.casas where id=c for update;select catalogo.precio into precio from public.catalogo where item=p_item;if precio is null then raise exception 'Ese producto no existe.';end if;if h.id is null then raise exception 'Primero crea una casa.';end if;if h.compras ? p_item then raise exception 'Ya está comprado.';end if;if h.dinero<precio then raise exception 'No alcanza el dinero de la casa.';end if;update public.casas set dinero=dinero-precio,compras=compras||jsonb_build_array(p_item) where id=c;return true;end;$$;
create function public.nc_posicion(p_token text,p_x real,p_z real) returns boolean language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);m public.miembros%rowtype;dt real;begin select * into m from public.miembros where jugador=j for update;if m.jugador is null then raise exception 'Primero entra a tu casa.';end if;if p_x is null or p_z is null or not(p_x between -9 and 7 and p_z between -5 and 5.5) then raise exception 'Posición inválida.';end if;if m.accion is not null then return false;end if;dt:=least(3,greatest(0,extract(epoch from(now()-m.pos_actualizada))))::real;if sqrt(power(p_x-m.x,2)+power(p_z-m.z,2))>dt*3.5+0.6 then return false;end if;update public.miembros set x=p_x,z=p_z,pos_actualizada=now() where jugador=j;return true;end;$$;
create function public.nc_actividad(p_token text,p_accion text) returns boolean language plpgsql security definer set search_path='' as $$
declare j uuid:=public.nc_identidad(p_token);c uuid;h public.casas%rowtype;m public.miembros%rowtype;q public.miembros%rowtype;a public.acciones%rowtype;sx real;sz real;begin select casa into c from public.miembros where jugador=j;if c is null then raise exception 'Primero entra a tu casa.';end if;perform public.nc_tick(c);select * into h from public.casas where id=c for update;select * into m from public.miembros where jugador=j for update;select * into a from public.acciones where clave=p_accion;if a.clave is null then raise exception 'Actividad inválida.';end if;if m.accion is not null then raise exception 'Termina tu actividad.';end if;if h.dinero<a.costo then raise exception 'No alcanza el dinero de la casa.';end if;if p_accion='trabajo' and m.trabajos>=1 then raise exception 'Ya trabajaste hoy. Solo puedes salir una vez por día.';end if;if a.item is not null and not(h.compras ? a.item) and not(a.item='tv' and h.compras ? 'tvgrande') then raise exception 'Primero compra ese mueble.';end if;
if a.pareja then select * into q from public.miembros where casa=c and jugador<>j for update;if q.jugador is null or q.accion is not null or q.pos_actualizada<now()-interval '15 seconds' or sqrt(power(m.x-q.x,2)+power(m.z-q.z,2))>2.8 then raise exception 'Tu pareja debe estar cerca, conectada y libre.';end if;else select v.x,v.z into sx,sz from (values ('cama',-4::real,-2::real),('ducha',4,-3),('inodoro',6,-3),('nevera',-5,3),('cocinar',-3,3),('trabajo',0,5.5),('tv',3,1),('radio',6,1),('sofa',4,3),('patio',-7,0),('armario',-6,-3))v(k,x,z) where v.k=p_accion;if sx is not null and sqrt(power(m.x-sx,2)+power(m.z-sz,2))>2.2 then raise exception 'Acércate al objeto.';end if;end if;
update public.casas set dinero=dinero-a.costo where id=c;update public.miembros set accion=p_accion,inicio=now(),fin=now()+make_interval(secs=>a.segundos),pareja=false where jugador=j;if a.pareja then update public.miembros set accion=p_accion,inicio=now(),fin=now()+make_interval(secs=>a.segundos),pareja=true where jugador=q.jugador;end if;return true;end;$$;
-- Revocar EXECUTE por defecto, incluso funciones internas. Solo exponer RPC verificadas.
revoke all on function public.nc_identidad(text),public.nc_tick(uuid) from public,anon,authenticated;
revoke all on function public.nc_register(text,text),public.nc_login(text,text),public.nc_personaje(text,jsonb),public.nc_crear(text),public.nc_unirse(text,text),public.nc_estado(text),public.nc_comprar(text,text),public.nc_posicion(text,real,real),public.nc_actividad(text,text) from public;
grant execute on function public.nc_register(text,text),public.nc_login(text,text),public.nc_personaje(text,jsonb),public.nc_crear(text),public.nc_unirse(text,text),public.nc_estado(text),public.nc_comprar(text,text),public.nc_posicion(text,real,real),public.nc_actividad(text,text) to anon,authenticated;
alter table public.casas replica identity full;
alter table public.miembros replica identity full;
do $$begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='casas') then alter publication supabase_realtime add table public.casas;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='miembros') then alter publication supabase_realtime add table public.miembros;end if;end$$;
-- Sin políticas SELECT anon: Realtime usa Broadcast de invalidación con canal aleatorio.
-- Cada receptor relee nc_estado con sesión validada; los mensajes no cambian dinero/posición.
notify pgrst,'reload schema';
commit;
